const base='/assets/art-review/xichuan-batch1/',manifest=await(await fetch(base+'manifest.json')).json(),groups=manifest.groups;
const names={'sprite-zhiyao-normal':{zh:'夏知遥 · 21 岁',en:'Xia Zhiyao · 21'},'sprite-shencheng-normal':{zh:'沈澄 · 21 岁',en:'Shen Cheng · 21'},'sprite-jibai-normal':{zh:'季白 · 23 岁',en:'Ji Bai · 23'},'bg-station':{zh:'汐川站',en:'Xichuan station'},'bg-oldhouse':{zh:'老房子院落',en:'The old courtyard'},'bg-cinema_dusk':{zh:'露天影院 · 黄昏',en:'Open-air cinema · Dusk'},'bg-campus':{zh:'大学社团广场',en:'University club plaza'},'bg-cafe':{zh:'海边咖啡馆',en:'Seawall café'},'bg-projection':{zh:'胶片放映室',en:'Film projection booth'}};
const copy={zh:{title:'汐川 · 首批美术候选',tag:'24 张候选 · 尚未采用',lead:'三位成年女主各四张透明底标准立绘；六个背景各两张。先选每个人的标准形象，再扩展表情。这里的选择只保存在当前浏览器，不会自动采用或改动游戏。',sprites:'人物立绘',backgrounds:'六个背景',demo:'叠放检查',matte:'检查透明边缘',checker:'棋盘格',light:'浅色底',dark:'深色底',export:'整理我的选择',count:n=>`已选 ${n} / 9 项`,source:'原始 PNG ↗',variant:'候选',frame:'原始尺寸',hero:'人物候选',back:'背景候选',overlay:'对话框留白',demoTag:'布局示意 · 非剧情台词',demoText:'仅检查立绘、背景和文字叠放，不代表采用。',note:'原始 PNG 未裁切、未改色。页面立绘 WebP 为保留透明通道的无损副本；背景仅编码。采用后的目标尺寸由 Claude 裁切接入。正式影院为露天场景；早期室内影院方向稿不属于本批。',handoff:'清单与审图 #112 ↗',exportLabel:'待审选择清单',none:'未选',close:'关闭原图预览'},en:{title:'Xichuan · First art candidates',tag:'24 CANDIDATES · NOT ADOPTED',lead:'Four transparent standard-sprite candidates for each of three adult leads, plus two options for each of six backgrounds. Choose identities before expression variants. Your picks stay in this browser; they do not adopt art or change the game.',sprites:'Character sprites',backgrounds:'Six backgrounds',demo:'Layering study',matte:'Inspect transparency',checker:'Checkerboard',light:'Light',dark:'Dark',export:'Collect my picks',count:n=>`${n} / 9 groups selected`,source:'Original PNG ↗',variant:'Candidate',frame:'Source size',hero:'Character candidate',back:'Background candidate',overlay:'Dialogue space',demoTag:'Layout study · Not story dialogue',demoText:'Checking sprites, backgrounds and text together; no art has been adopted.',note:'Original PNGs are uncropped and unretouched. Sprite WebP previews preserve alpha losslessly; background previews are encoded only. Claude will prepare final target dimensions after approval. The story cinema is open-air; earlier indoor-cinema concepts are outside this batch.',handoff:'Jobs and review #112 ↗',exportLabel:'Pending-review picks',none:'Not selected',close:'Close image preview'}};
const storeKey='sd.art.xichuan.batch1.picks.v1',root=document.querySelector('#review'),dialog=document.querySelector('#full');let lang='zh',tab='sprite',matte='checker',picks={},exported=false,overlay=true;
let hero='sprite-zhiyao-normal:a',back='bg-cinema_dusk:a';try{const l=localStorage.getItem('sd.lang');if(['zh','en'].includes(l))lang=l;const saved=JSON.parse(localStorage.getItem(storeKey)||'{}');for(const g of groups)if(g.candidates.some(c=>c.variant===saved[g.id]))picks[g.id]=saved[g.id];}catch{}
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),name=g=>names[g.id][lang],src=c=>base+c.preview,raw=c=>'https://raw.githubusercontent.com/storyloveai/ocai/refs/heads/codex/coastal-vn-art-pilot/game/xichuan/art/candidates/batch1/'+c.source;
const find=value=>{const[id,variant]=value.split(':');const g=groups.find(g=>g.id===id);return g?.candidates.find(c=>c.variant===variant);};
const selectedText=()=>['#112 · '+copy[lang].exportLabel,...groups.map(g=>g.id+'\t'+(picks[g.id]?.toUpperCase()||copy[lang].none))].join('\n');
function updatePicks(){root.querySelector('[data-count]').textContent=copy[lang].count(Object.keys(picks).length);root.querySelectorAll('.card').forEach(c=>c.classList.toggle('picked',Boolean(c.querySelector('input:checked'))));const t=root.querySelector('textarea');if(t)t.value=selectedText();}
function draw(){const c=copy[lang];document.documentElement.lang=lang;document.title=c.title+' · StoryDate';document.body.classList.toggle('light',matte==='light');document.body.classList.toggle('dark',matte==='dark');document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));root.innerHTML=`<div class="kicker">${c.tag}</div><h1>${c.title}</h1><p>${c.lead}</p><div class="controls"><label>${c.matte} <select data-matte aria-label="${c.matte}">${['checker','light','dark'].map(v=>`<option value="${v}" ${matte===v?'selected':''}>${c[v]}</option>`).join('')}</select></label><button data-export>${c.export}</button><span data-count></span></div><textarea aria-label="${c.exportLabel}" readonly ${exported?'':'hidden'}></textarea><div class="tabs" role="tablist">${[['sprite',c.sprites],['bg',c.backgrounds],['demo',c.demo]].map(([v,t])=>`<button role="tab" data-tab="${v}" aria-selected="${tab===v}">${t}</button>`).join('')}</div>${tab==='demo'?`<div class="demo-controls"><label>${c.hero}<select data-hero>${groups.filter(g=>g.kind==='sprite').flatMap(g=>g.candidates.map(x=>`<option value="${g.id}:${x.variant}" ${hero===g.id+':'+x.variant?'selected':''}>${name(g)} · ${x.variant.toUpperCase()}</option>`)).join('')}</select></label><label>${c.back}<select data-back>${groups.filter(g=>g.kind==='bg').flatMap(g=>g.candidates.map(x=>`<option value="${g.id}:${x.variant}" ${back===g.id+':'+x.variant?'selected':''}>${name(g)} · ${x.variant.toUpperCase()}</option>`)).join('')}</select></label><button data-overlay aria-pressed="${overlay}">${c.overlay}</button></div><div class="stage"><img class="backdrop" src="${src(find(back))}" alt="${c.back}"><img class="sprite" src="${src(find(hero))}" alt="${c.hero}">${overlay?`<div class="dialogue"><b>${c.demoTag}</b><p>${c.demoText}</p></div>`:''}</div>`:groups.filter(g=>g.kind===tab).map(g=>`<section class="group ${g.kind}"><div class="group-head"><h2>${name(g)}</h2><small>${g.kind==='sprite'?'A / B / C / D':'A / B'}</small></div><div class="cards">${g.candidates.map(x=>`<article class="card"><button class="picture ${g.kind==='sprite'?'checker':''}" data-full="${g.id}:${x.variant}" aria-label="${safe(name(g)+' '+x.variant.toUpperCase())}"><img src="${src(x)}" loading="lazy" width="${x.dimensions[0]}" height="${x.dimensions[1]}" alt="${safe(name(g)+' '+c.variant+' '+x.variant.toUpperCase())}"></button><div class="label"><label><input type="radio" name="${g.id}" value="${x.variant}" ${picks[g.id]===x.variant?'checked':''}>${c.variant} ${x.variant.toUpperCase()}</label><a href="${raw(x)}" target="_blank" rel="noopener">${c.source}</a><small>${c.frame} ${x.dimensions.join(' × ')}</small></div></article>`).join('')}</div></section>`).join('')}<p class="note">${c.note}<br><a href="https://github.com/storyloveai/ocai/issues/112" target="_blank" rel="noopener">${c.handoff}</a></p>`;updatePicks();root.querySelector('textarea').value=selectedText();dialog.querySelector('.close').setAttribute('aria-label',c.close);}
root.addEventListener('change',e=>{const t=e.target;if(t.matches('input[type=radio]')){const g=groups.find(g=>g.id===t.name);if(!g?.candidates.some(c=>c.variant===t.value))return;picks[g.id]=t.value;try{localStorage.setItem(storeKey,JSON.stringify(picks));}catch{}updatePicks();}else if(t.hasAttribute('data-matte')){matte=t.value;draw();}else if(t.hasAttribute('data-hero')){hero=t.value;draw();}else if(t.hasAttribute('data-back')){back=t.value;draw();}});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;draw();}else if(b.hasAttribute('data-export')){exported=!exported;const t=root.querySelector('textarea');t.hidden=!exported;t.value=selectedText();if(exported){t.focus();t.select();}}else if(b.hasAttribute('data-overlay')){overlay=!overlay;draw();}else if(b.dataset.full){const x=find(b.dataset.full);if(!x)return;dialog.querySelector('img').src=src(x);dialog.querySelector('img').alt=b.getAttribute('aria-label');dialog.querySelector('b').textContent=b.getAttribute('aria-label');dialog.showModal();}});
dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;try{localStorage.setItem('sd.lang',lang);}catch{}draw();});draw();
